const drawOwl = () => {
  // Draw branch
  ctx.fillStyle = '#8B4513';
  ctx.fillRect(180, 250, 40, 150);

  // Draw owl body
  ctx.fillStyle = '#8B4513';
  ctx.beginPath();
  ctx.arc(200, 200, 40, 0, Math.PI * 2);
  ctx.fill();

  // Draw owl head
  ctx.fillStyle = '#8B4513';
  ctx.beginPath();
  ctx.arc(200, 150, 30, 0, Math.PI * 2);
  ctx.fill();

  // Draw owl eyes
  ctx.fillStyle = '#000';
  ctx.beginPath();
  ctx.arc(185, 140, 6, 0, Math.PI * 2);
  ctx.arc(215, 140, 6, 0, Math.PI * 2);
  ctx.fill();

  // Draw owl pupils
  ctx.fillStyle = '#FFF';
  ctx.beginPath();
  ctx.arc(185, 140, 2, 0, Math.PI * 2);
  ctx.arc(215, 140, 2, 0, Math.PI * 2);
  ctx.fill();

  // Draw owl beak
  ctx.fillStyle = '#FF8C00';
  ctx.beginPath();
  ctx.moveTo(200, 160);
  ctx.lineTo(220, 170);
  ctx.lineTo(200, 175);
  ctx.closePath();
  ctx.fill();

  // Draw owl feathers
  ctx.fillStyle = '#A0522D';
  ctx.fillRect(180, 190, 10, 15);
  ctx.fillRect(210, 190, 10, 15);
  ctx.fillRect(190, 180, 20, 10);

  // Draw wise expression (small smile)
  ctx.strokeStyle = '#000';
  ctx.lineWidth = 2;
  ctx.beginPath();
  ctx.arc(200, 165, 8, 0, Math.PI);
  ctx.stroke();
};

