function drawCandle() {
  // Draw candle base
  ctx.fillStyle = '#eee';
  ctx.fillRect(180, 250, 40, 100);

  // Draw candle wax
  ctx.fillStyle = '#fff';
  ctx.fillRect(185, 255, 30, 90);

  // Draw wick
  ctx.fillStyle = '#333';
  ctx.fillRect(200, 250, 2, 10);

  // Draw flame
  const flameHeight = 30 + Math.sin(Date.now() / 100) * 10;
  const flameWidth = 15 + Math.cos(Date.now() / 80) * 5;

  // Flame core (yellow)
  ctx.fillStyle = '#ffff00';
  ctx.beginPath();
  ctx.ellipse(201, 240, flameWidth/2, flameHeight/2, 0, 0, Math.PI * 2);
  ctx.fill();

  // Flame outer (orange)
  ctx.fillStyle = '#ff8800';
  ctx.beginPath();
  ctx.ellipse(201, 240, flameWidth, flameHeight, 0, 0, Math.PI * 2);
  ctx.fill();

  // Flame glow
  ctx.fillStyle = '#ff4400';
  ctx.beginPath();
  ctx.ellipse(201, 240, flameWidth * 1.5, flameHeight * 1.5, 0, 0, Math.PI * 2);
  ctx.fill();
}

