function drawCandle() {
  // Draw candle base
  ctx.fillStyle = '#eee';
  ctx.fillRect(180, 250, 40, 100);

  // Draw candle wax
  ctx.fillStyle = '#fff';
  ctx.fillRect(185, 255, 30, 90);

  // Draw flame
  const flameHeight = 30 + Math.sin(Date.now() / 100) * 10;
  const flameY = 250 - flameHeight;

  // Flame core (yellow)
  ctx.fillStyle = '#ff9';
  ctx.beginPath();
  ctx.arc(200, flameY, 8, 0, Math.PI * 2);
  ctx.fill();

  // Flame outer (orange)
  ctx.fillStyle = '#f93';
  ctx.beginPath();
  ctx.arc(200, flameY, 12, 0, Math.PI * 2);
  ctx.fill();

  // Flame flicker effect
  ctx.fillStyle = '#ff6';
  ctx.beginPath();
  ctx.arc(200, flameY - 3, 6, 0, Math.PI * 2);
  ctx.fill();

  // Draw shadow
  ctx.fillStyle = 'rgba(0,0,0,0.1)';
  ctx.fillRect(190, 350, 20, 5);
}

