// Animation loop
function animate() {
    // Clear canvas
    ctx.fillStyle = '#000';
    ctx.fillRect(0, 0, W, H);

    // Redraw stars
    ctx.fillStyle = '#fff';
    for (let i = 0; i < 100; i++) {
        const x = Math.random() * W;
        const y = Math.random() * H;
        const size = Math.random() * 2;
        ctx.fillRect(x, y, size, size);
    }

    // Redraw ground
    ctx.fillStyle = '#555';
    ctx.fillRect(0, H - 20, W, 20);

    // Update rocket position
    rocketY -= 2;
    flameHeight = 15 + Math.sin(flameOffset) * 5;
    flameOffset += 0.3;

    // Draw rocket body
    ctx.fillStyle = '#f00';
    ctx.fillRect(W/2 - 10, rocketY, 20, 40);

    // Draw rocket top
    ctx.fillStyle = '#ff0';
    ctx.beginPath();
    ctx.moveTo(W/2 - 15, rocketY);
    ctx.lineTo(W/2 + 15, rocketY);
    ctx.lineTo(W/2, rocketY - 15);
    ctx.closePath();
    ctx.fill();

    // Draw flames
    ctx.fillStyle = '#ff8800';
    ctx.fillRect(W/2 - 8, rocketY + 40, 16, flameHeight);

    ctx.fillStyle = '#ffff00';
    ctx.fillRect(W/2 - 6, rocketY + 40, 12, flameHeight * 0.6);

    // Stop animation when rocket leaves screen
    if (rocketY > -50) {
        requestAnimationFrame(animate);
    }
}

