const drawGhost = () => {
  // Draw graveyard background
  ctx.fillStyle = '#1a1a1a';
  ctx.fillRect(0, 0, W, H);

  // Draw moon
  ctx.fillStyle = '#f0f0f0';
  ctx.beginPath();
  ctx.arc(320, 60, 30, 0, Math.PI * 2);
  ctx.fill();

  // Draw grave stones
  ctx.fillStyle = '#555';
  for (let i = 0; i < 8; i++) {
    const x = 40 + i * 45;
    const y = 300;
    // Stone base
    ctx.fillRect(x, y, 20, 20);
    // Stone top
    ctx.fillRect(x - 5, y - 20, 30, 15);
  }

  // Draw ghost body
  ctx.fillStyle = '#f0f0f0';
  ctx.beginPath();
  ctx.arc(200, 200, 40, 0, Math.PI * 2);
  ctx.fill();

  // Draw ghost eyes
  ctx.fillStyle = '#000';
  ctx.beginPath();
  ctx.arc(180, 190, 8, 0, Math.PI * 2);
  ctx.arc(220, 190, 8, 0, Math.PI * 2);
  ctx.fill();

  // Draw ghost pupils
  ctx.fillStyle = '#fff';
  ctx.beginPath();
  ctx.arc(180, 190, 3, 0, Math.PI * 2);
  ctx.arc(220, 190, 3, 0, Math.PI * 2);
  ctx.fill();

  // Draw ghost mouth
  ctx.strokeStyle = '#000';
  ctx.lineWidth = 2;
  ctx.beginPath();
  ctx.arc(200, 220, 10, 0, Math.PI);
  ctx.stroke();

  // Draw ghost arms
  ctx.fillStyle = '#f0f0f0';
  ctx.fillRect(140, 180, 20, 20);
  ctx.fillRect(240, 180, 20, 20);

  // Draw ghost feet
  ctx.fillRect(170, 240, 10, 10);
  ctx.fillRect(220, 240, 10, 10);
};

