function drawCandle() {
    // Draw flame
    const flameX = 190;
    const flameY = 80;
    const flameHeight = 60 + Math.sin(Date.now() / 100) * 10;

    // Flame base (yellow)
    ctx.fillStyle = '#ffff00';
    ctx.beginPath();
    ctx.arc(flameX, flameY, 8, 0, Math.PI * 2);
    ctx.fill();

    // Flame middle (orange)
    ctx.fillStyle = '#ff8800';
    ctx.beginPath();
    ctx.arc(flameX, flameY - flameHeight/3, 6, 0, Math.PI * 2);
    ctx.fill();

    // Flame tip (red)
    ctx.fillStyle = '#ff0000';
    ctx.beginPath();
    ctx.arc(flameX, flameY - flameHeight/2, 4, 0, Math.PI * 2);
    ctx.fill();

    // Draw candle body
    ctx.fillStyle = '#ffffff';
    ctx.fillRect(180, 140, 40, 180);

    // Draw candle wax drips
    ctx.fillStyle = '#eeeeee';
    ctx.fillRect(175, 150, 5, 15);
    ctx.fillRect(220, 160, 5, 20);
    ctx.fillRect(185, 200, 5, 10);

    // Draw candle wick
    ctx.fillStyle = '#000000';
    ctx.fillRect(198, 140, 4, 10);
}

