function drawCandle() {
    // Draw background
    ctx.fillStyle = '#000';
    ctx.fillRect(0, 0, W, H);

    // Draw candle base
    ctx.fillStyle = '#aaa';
    ctx.fillRect(180, 300, 40, 60);

    // Draw candle body
    ctx.fillStyle = '#fff';
    ctx.fillRect(190, 200, 20, 100);

    // Draw flame with flickering effect
    const flameX = 200;
    const flameY = 180;
    const flameSize = 15 + Math.random() * 10;

    // Flame core (yellow)
    ctx.fillStyle = '#ffff00';
    ctx.beginPath();
    ctx.arc(flameX, flameY, flameSize, 0, Math.PI * 2);
    ctx.fill();

    // Flame outer glow (orange)
    ctx.fillStyle = '#ff8800';
    ctx.beginPath();
    ctx.arc(flameX, flameY, flameSize * 1.5, 0, Math.PI * 2);
    ctx.fill();

    // Draw flame shadow
    ctx.fillStyle = '#222';
    ctx.beginPath();
    ctx.arc(flameX, flameY + 5, flameSize * 0.8, 0, Math.PI * 2);
    ctx.fill();
}

