function drawCandle() {
  // Draw candle base
  ctx.fillStyle = '#eee';
  ctx.fillRect(180, 250, 40, 100);

  // Draw candle wax
  ctx.fillStyle = '#fff';
  ctx.fillRect(185, 255, 30, 90);

  // Draw wick
  ctx.fillStyle = '#333';
  ctx.fillRect(200, 250, 2, 10);

  // Draw flame
  const flameHeight = 20 + Math.random() * 15;
  const flameWidth = 8 + Math.random() * 8;

  // Flame core (yellow)
  ctx.fillStyle = '#ffcc00';
  ctx.beginPath();
  ctx.ellipse(201, 240, flameWidth/2, flameHeight, 0, 0, Math.PI * 2);
  ctx.fill();

  // Flame outer (orange)
  ctx.fillStyle = '#ff6600';
  ctx.beginPath();
  ctx.ellipse(201, 240, flameWidth/3, flameHeight/2, 0, 0, Math.PI * 2);
  ctx.fill();
}

