function drawFlower(x, y, color) {
    // Stem
    ctx.fillStyle = '#4CAF50';
    ctx.fillRect(x, y, 4, 40);

    // Flower head
    ctx.fillStyle = color;
    ctx.beginPath();
    ctx.arc(x + 2, y, 10, 0, Math.PI * 2);
    ctx.fill();

    // Center
    ctx.fillStyle = '#FFD700';
    ctx.beginPath();
    ctx.arc(x + 2, y, 4, 0, Math.PI * 2);
    ctx.fill();
}

