// Draw rocket
let rocketY = H - 20;
let thrust = 0;

// Animation loop
function animate() {
    // Clear canvas
    ctx.fillStyle = '#000';
    ctx.fillRect(0, 0, W, H);

    // Redraw stars
    ctx.fillStyle = '#fff';
    for (let i = 0; i < 100; i++) {
        const x = Math.random() * W;
        const y = Math.random() * H;
        const size = Math.random() * 2;
        ctx.fillRect(x, y, size, size);
    }

    // Draw ground
    ctx.fillStyle = '#555';
    ctx.fillRect(0, H - 20, W, 20);

    // Update rocket position
    rocketY -= 2;
    thrust += 0.1;

    // Draw rocket body
    ctx.fillStyle = '#f00';
    ctx.fillRect(190, rocketY, 20, 40);

    // Draw rocket nose
    ctx.fillStyle = '#ff0000';
    ctx.beginPath();
    ctx.moveTo(190, rocketY);
    ctx.lineTo(210, rocketY);
    ctx.lineTo(200, rocketY - 10);
    ctx.closePath();
    ctx.fill();

    // Draw rocket fins
    ctx.fillStyle = '#ff0000';
    ctx.fillRect(185, rocketY + 25, 10, 15);
    ctx.fillRect(205, rocketY + 25, 10, 15);

    // Draw thrust flames
    if (thrust < 10) {
        ctx.fillStyle = '#ff9900';
        ctx.beginPath();
        ctx.moveTo(195, rocketY + 40);
        ctx.lineTo(205, rocketY + 40);
        ctx.lineTo(200, rocketY + 40 + thrust);
        ctx.closePath();
        ctx.fill();

        ctx.fillStyle = '#ffff00';
        ctx.beginPath();
        ctx.moveTo(195, rocketY + 40);
        ctx.lineTo(205, rocketY + 40);
        ctx.lineTo(200, rocketY + 40 + thrust * 0.7);
        ctx.closePath();
        ctx.fill();
    }

    // Continue animation until rocket leaves screen
    if (rocketY > -50) {
        requestAnimationFrame(animate);
    }
}

